/**
 * The learner's in-progress answer to a generated BYOC tree, and the pure
 * transitions over it. Kept out of the component so the answer shape and the
 * grading can be tested without rendering.
 */
import type { GeneratedChoiceTree, Verdict } from '@iterahq/activity-spec';
import type { OptionTone } from '@/consts/byocTone';

/**
 * The graded half of the union. `build_context` is deliberately out: it has no
 * gabarito to look up, so every function here would need a branch that returns
 * "always right" — a dead path that reads like grading and isn't.
 */
export type GradedChoiceTree = Extract<
  GeneratedChoiceTree,
  { interaction: 'pick_best' | 'judge_each' }
>;

/** One option id (pick_best), or a verdict per option (judge_each). */
export type ByocAnswer =
  | { interaction: 'pick_best'; selected: string | null }
  | { interaction: 'judge_each'; verdicts: Record<string, Verdict> };

export function emptyAnswer(tree: GradedChoiceTree): ByocAnswer {
  return tree.interaction === 'pick_best'
    ? { interaction: 'pick_best', selected: null }
    : { interaction: 'judge_each', verdicts: {} };
}

export function withVerdict(prev: ByocAnswer, optionId: string, verdict: Verdict): ByocAnswer {
  if (prev.interaction !== 'judge_each') return prev;
  return { interaction: 'judge_each', verdicts: { ...prev.verdicts, [optionId]: verdict } };
}

/** Whether the learner has answered enough for "Enviar" to be meaningful. */
export function isAnswerComplete(tree: GradedChoiceTree, answer: ByocAnswer): boolean {
  if (tree.interaction === 'pick_best') {
    return answer.interaction === 'pick_best' && answer.selected !== null;
  }
  if (answer.interaction !== 'judge_each') return false;
  return tree.options.every((o) => answer.verdicts[o.id] !== undefined);
}

/**
 * Correction is a pure lookup against the gabarito the generation embedded
 * (ADR-13) — no model call in the answer path. pick_best: the one right path.
 * judge_each: EVERY option classified right.
 */
export function gradeByoc(tree: GradedChoiceTree, answer: ByocAnswer): boolean {
  if (tree.interaction === 'pick_best') {
    return answer.interaction === 'pick_best' && answer.selected === tree.correct_option_id;
  }
  if (answer.interaction !== 'judge_each') return false;
  return tree.options.every((o) => answer.verdicts[o.id] === o.expected_verdict);
}

/** Visual state of one option, before (`shown` false) and after grading. */
export function toneFor(
  tree: GradedChoiceTree,
  answer: ByocAnswer,
  optionId: string,
  shown: boolean
): OptionTone {
  if (tree.interaction === 'pick_best') {
    const chosen = answer.interaction === 'pick_best' && answer.selected === optionId;
    if (!shown) return chosen ? 'chosen' : 'neutral';
    if (optionId === tree.correct_option_id) return 'correct';
    return chosen ? 'wrong' : 'neutral';
  }
  const given = answer.interaction === 'judge_each' ? answer.verdicts[optionId] : undefined;
  if (!shown) return given ? 'chosen' : 'neutral';
  // Nothing to mark wrong when they never classified it — the live timer can
  // reveal on a whole cohort that has not answered, and painting every card red
  // scolds them for the clock. The key shows up on the verdict buttons instead.
  if (given === undefined) return 'neutral';
  const expected = tree.options.find((o) => o.id === optionId)?.expected_verdict;
  return given === expected ? 'correct' : 'wrong';
}
